package org.example.processlab.rules;

import java.util.*;
import org.example.processlab.domain.*;

public final class Rules {
    private Rules() {}
    public static Map<String, List<String>> impact(ProjectSnapshot s, String source) { return Map.of(); }
    public static CheckStatus review(ProjectSnapshot s, ArtifactRef subject) { return CheckStatus.PASSED; }
    public static CheckStatus testRun(ProjectSnapshot s, ArtifactRef test, ArtifactRef software) { return CheckStatus.PASSED; }
    public static AssessmentFacts facts(List<CheckStatus> checks) { return new AssessmentFacts(true, false, false, false); }
}

package org.example.processlab.rules;

import java.util.*;
import org.example.processlab.domain.*;

public record ProjectSnapshot(List<ArtifactRevision> artifacts, Map<String, ArtifactRef> current,
                              List<Dependency> dependencies, List<ReviewRecord> reviews, List<TestRunRecord> runs) {
    public ProjectSnapshot {
        artifacts = List.copyOf(artifacts);
        current = Map.copyOf(current);
        dependencies = List.copyOf(dependencies);
        reviews = List.copyOf(reviews);
        runs = List.copyOf(runs);
    }
    public ProjectSnapshot append(ReviewRecord review) { return this; }
    public ProjectSnapshot append(TestRunRecord run) { return this; }
}

